    trigger_threshold: float = 0.75      # 达到预算的 75% 时触发压缩
    keep_recent: int = 6                 # 保留最近 N 条消息
    protect_first: int = 2              # 保护前 N 条（system + 首次问候）
    protect_last: int = 4               # 保护后 N 条
    min_messages_to_compact: int = 8    # 至少 N 条消息才触发压缩
